            key = (d, (nx + ny))
            if best is None or key < best[0]:
                best = (key, (dx, dy))
        return [best[1][0], best[1][1]] if best else [0, 0]

    # Choose target deterministically by "advantage" over opponent and then steer by best immediate move.
    best_target = None
    for rx, ry in resources:
        ds = cheb(sx, sy, rx, ry)
        do = cheb(ox, oy, rx, ry)
        # resource-denier: value cells opponent can reach sooner; if we can still out-reach, prefer it.
        # also bias slightly toward closer resources to reduce dithering.
        adv = (do - ds) * 10 - ds
        # discourage target that is currently very close to opponent
        close_pen = -3 if do <= 1 else 0
        score = adv + close_pen
        tie = (ds, do, rx, ry)
        if best_target is None or (score, -do, -ds, -rx, -ry, tie) > best_target[0]:
            best_target = (score, (rx, ry))
    tx, ty = best_target[1]

    # One-step lookahead: pick move that maximizes expected advantage and reduces getting blocked near target.
    best = None
    for dx, dy, nx, ny in legal:
        myd = cheb(nx, ny, tx, ty)
        opd = cheb(ox, oy, tx, ty)
        # bonus if we move closer than opponent would be after their greedy step
        # approximate opponent next step with best cheb move to target among legal moves for opponent
        olegal = []
        for odx, ody in moves:
            onx, ony = ox + odx, oy + ody
            if inb(onx, ony) and (onx, ony) not in obs:
                olegal.append((onx, ony))
        if olegal:
            best_op = min(olegal, key=lambda p: cheb(p[0], p[1], tx, ty))
            opp_next = cheb(best_op[0], best_op[1], tx, ty)
        else:
            opp_next = opd
        advantage = (opp_next - myd) * 12 - myd
        # slight repulsion from obstacles to prevent obstacle hits when clustered
        near_obs = 0
        for ax in (-1, 0, 1):
            for ay in (-1, 0, 1):
                if ax == 0 and ay == 0:
                    continue
                if (nx + ax, ny + ay) in obs:
                    near_obs += 1
        key = (advantage, -near_obs, -nx, -ny, dx, dy)
        if best is None or key > best[0]:
            best = (key, (dx, dy))
    return [best[1][0], best[1][1]]

